/// <summary>Le contrat du vrai module de billets, tel que décrit par la spec.</summary>
public class MoneyDispenserTests
{
    [Theory]
    [InlineData(1, 0, 0)]
    [InlineData(4, 0, 0)]
    [InlineData(1, 2, 1)]
    [InlineData(0, 0, 4)]
    public void Dispense_removes_notes_in_one_pass(int f, int t, int n)
    {
