    }

    [Fact]
    public void Deposit_matches_spec_for_every_deposit_stock_and_jam()
    {
        var failures = new List<string>();
        var accounts = new[] { Acc(0, 0), Acc(10, 30), Acc(170, 200), Acc(250, 100) };
        foreach (var account in accounts)
