                ? Sum(dispenser.LoadCalls) == notes
                : dispenser.LoadCalls.Count == 0;

            if (result.Status != expected.Status || result.Notes != NoteCounts.None || result.Fee != 0
                || result.Account != expected.Account || dispenser.Stock != expected.Stock
